package com.team11.insurance.quotes;

import java.math.BigDecimal;
import java.time.Instant;

import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.Table;

/**
 * Persistence entity representing an insurance quote calculation (INS-F-005, INS-F-006).
 * Generated by the Quoting Engine (C5) for motor (2W/4W) or health insurance.
 */
@Entity
@Table(name = "quotes", indexes = {
        @Index(name = "idx_quote_customer", columnList = "customer_id"),
        @Index(name = "idx_quote_plan", columnList = "plan_id"),
        @Index(name = "idx_quote_product_type", columnList = "product_type")
})
public class Quote {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "customer_id", nullable = false)
    private Long customerId;

    @Column(name = "insurer_id")
    private Long insurerId;

    @Column(name = "plan_id", nullable = false)
    private Long planId;

    /**
     * Product type identifier: TWO_WHEELER, FOUR_WHEELER, or HEALTH.
     */
    @Column(name = "product_type", nullable = false, length = 20)
    private String productType;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal premium;

    /**
     * JSON text containing the detailed premium breakdown (base, add-ons, taxes, discounts).
     */
    @Column(name = "breakdown_json", columnDefinition = "TEXT")
    private String breakdownJson;

    /**
     * JSON text containing input parameters (vehicle info, member details, sum insured, add-ons).
     */
    @Column(name = "details_json", columnDefinition = "TEXT")
    private String detailsJson;

    @Column(name = "valid_until")
    private Instant validUntil;

    @CreationTimestamp
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @UpdateTimestamp
    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    public Quote() {
    }

    public Quote(Long customerId, Long insurerId, Long planId, String productType,
                 BigDecimal premium, String breakdownJson, String detailsJson, Instant validUntil) {
        this.customerId = customerId;
        this.insurerId = insurerId;
        this.planId = planId;
        this.productType = productType;
        this.premium = premium;
        this.breakdownJson = breakdownJson;
        this.detailsJson = detailsJson;
        this.validUntil = validUntil;
    }

    public Long getId() {
        return id;
    }

    public Long getCustomerId() {
        return customerId;
    }

    public void setCustomerId(Long customerId) {
        this.customerId = customerId;
    }

    public Long getInsurerId() {
        return insurerId;
    }

    public void setInsurerId(Long insurerId) {
        this.insurerId = insurerId;
    }

    public Long getPlanId() {
        return planId;
    }

    public void setPlanId(Long planId) {
        this.planId = planId;
    }

    public String getProductType() {
        return productType;
    }

    public void setProductType(String productType) {
        this.productType = productType;
    }

    public BigDecimal getPremium() {
        return premium;
    }

    public void setPremium(BigDecimal premium) {
        this.premium = premium;
    }

    public String getBreakdownJson() {
        return breakdownJson;
    }

    public void setBreakdownJson(String breakdownJson) {
        this.breakdownJson = breakdownJson;
    }

    public String getDetailsJson() {
        return detailsJson;
    }

    public void setDetailsJson(String detailsJson) {
        this.detailsJson = detailsJson;
    }

    public Instant getValidUntil() {
        return validUntil;
    }

    public void setValidUntil(Instant validUntil) {
        this.validUntil = validUntil;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }
}
